":"barbell","exerciseType":"compound","primary":["quads"],"secondary":["calves","glutes","hamstrings","back"]},{"id":"10000000-1b9a-4056-8500-386a6a21e12c","name":"Wide Stance Stiff Legs","equipment":"barbell","exerciseType":"compound","primary":["hamstrings"],"secondary":["quads","glutes","back"]},{"id":"10000000-3c5b-4bc7-83aa-76b971f2ca47","name":"Wide-Grip Barbell Bench Press","equipment":"barbell","exerciseType":"compound","primary":["chest"],"secondary":["shoulders","triceps"]},{"id":"10000000-9647-4533-829a-a6561b70af20","name":"Wide-Grip Decline Barbell Bench Press","equipment":"barbell","exerciseType":"compound","primary":["chest"],"secondary":["shoulders","triceps"]},{"id":"10000000-99a6-475d-833c-eae4446f5499","name":"Wide-Grip Decline Barbell Pullover","equipment":"barbell","exerciseType":"compound","primary":["chest"],"secondary":["shoulders","triceps"]},{"id":"10000000-550c-4ee6-8150-382d529ffda9","name":"Wide-Grip Lat Pulldown","equipment":"cable","exerciseType":"compound","primary":["back"],"secondary":["biceps","shoulders"]},{"id":"10000000-ec68-4cb2-8431-ae8f84479ca2","name":"Wide-Grip Pulldown Behind The Neck","equipment":"cable","exerciseType":"compound","primary":["back"],"secondary":["biceps","shoulders"]},{"id":"10000000-0c58-4e2e-8c6c-e438629b45e6","name":"Wide-Grip Rear Pull-Up","equipment":"bodyweight","exerciseType":"compound","primary":["back"],"secondary":["biceps","shoulders"]},{"id":"10000000-0e27-4e51-84db-6315c36960c7","name":"Wide-Grip Standing Barbell Curl","equipment":"barbell","exerciseType":"isolation","primary":["biceps"],"secondary":[]},{"id":"10000000-cd37-4f1a-8b7e-4da8153c49a2","name":"Wrist Roller","equipment":"other","exerciseType":"isolation","primary":["forearms"],"secondary":["shoulders"]},{"id":"10000000-1033-4025-849d-07920dc45652","name":"Wrist Rotations with Straight Bar","equipment":"barbell","exerciseType":"isolation","primary":["forearms"],"secondary":[]},{"id":"10000000-aa58-49b4-8a9b-62d81b3bb4e6","name":"Zercher Squats","equipment":"barbell","exerciseType":"compound","primary":["quads"],"secondary":["calves","glutes","hamstrings"]},{"id":"10000000-7af5-4d98-82de-610ee6d514a6","name":"Zottman Curl","equipment":"dumbbell","exerciseType":"isolation","primary":["biceps"],"secondary":["forearms"]},{"id":"10000000-906d-4d93-87cf-8b18a84ff738","name":"Zottman Preacher Curl","equipment":"dumbbell","exerciseType":"isolation","primary":["biceps"],"secondary":["forearms"]}]'::jsonb) AS catalog(
  id uuid,
  name text,
  equipment text,
  "exerciseType" text,
  "primary" jsonb,
  "secondary" jsonb
);

DO $$
DECLARE conflict_names text;
BEGIN
  SELECT string_agg(catalog.name, ', ' ORDER BY catalog.name)
  INTO conflict_names
  FROM catalog_import catalog
  JOIN exercises existing ON lower(existing.name) = lower(catalog.name)
  WHERE existing.created_by_user_id IS NOT NULL;

  IF conflict_names IS NOT NULL THEN
    RAISE NOTICE 'System exercise catalog preserved user-owned conflicts for manual review: %', conflict_names;
  END IF;
END $$;

INSERT INTO exercises (
  id, name, equipment, exercise_type, primary_muscle_group_id, created_by_user_id
)
SELECT
  catalog.id,
  catalog.name,
  catalog.equipment,
  catalog."exerciseType",
  primary_group.id,
  NULL
FROM catalog_import catalog
JOIN LATERAL jsonb_array_elements_text(catalog."primary") primary_slug ON true
JOIN muscle_groups primary_group ON primary_group.slug = primary_slug
WHERE primary_slug = catalog."primary"->>0
  AND NOT EXISTS (
    SELECT 1 FROM exercises existing WHERE lower(existing.name) = lower(catalog.name)
  );

UPDATE exercises
SET
  equipment = catalog.equipment,
  exercise_type = catalog."exerciseType",
  updated_at = now()
FROM catalog_import catalog
WHERE exercises.id = catalog.id
  AND exercises.created_by_user_id IS NULL;

INSERT INTO exercise_muscle_groups (exercise_id, muscle_group_id, role)
SELECT catalog.id, muscle_groups.id, 'PRIMARY'
FROM catalog_import catalog
JOIN exercises ON exercises.id = catalog.id AND exercises.created_by_user_id IS NULL
JOIN LATERAL jsonb_array_elements_text(catalog."primary") muscle_slug ON true
JOIN muscle_groups ON muscle_groups.slug = muscle_slug
ON CONFLICT (exercise_id, muscle_group_id) DO UPDATE SET role = 'PRIMARY';

INSERT INTO exercise_muscle_groups (exercise_id, muscle_group_id, role)
SELECT catalog.id, muscle_groups.id, 'SECONDARY'
FROM catalog_import catalog
JOIN exercises ON exercises.id = catalog.id AND exercises.created_by_user_id IS NULL
JOIN LATERAL jsonb_array_elements_text(catalog."secondary") muscle_slug ON true
JOIN muscle_groups ON muscle_groups.slug = muscle_slug
ON CONFLICT (exercise_id, muscle_group_id) DO NOTHING;

INSERT INTO exercise_secondary_muscles (exercise_id, muscle_group_id)
SELECT catalog.id, muscle_groups.id
FROM catalog_import catalog
JOIN exercises ON exercises.id = catalog.id AND exercises.created_by_user_id IS NULL
JOIN LATERAL jsonb_array_elements_text(catalog."secondary") muscle_slug ON true
JOIN muscle_groups ON muscle_groups.slug = muscle_slug
ON CONFLICT (exercise_id, muscle_group_id) DO NOTHING;

-- Down Migration

CREATE TEMP TABLE catalog_delete_candidates ON COMMIT DROP AS
SELECT id
FROM exercises
WHERE id::text LIKE '10000000-%'
  AND NOT EXISTS (
    SELECT 1 FROM session_exercises WHERE session_exercises.exercise_id = exercises.id
  )
  AND NOT EXISTS (
    SELECT 1 FROM workout_template_exercises WHERE workout_template_exercises.exercise_id = exercises.id
  );

DELETE FROM exercise_secondary_muscles
WHERE exercise_id IN (SELECT id FROM catalog_delete_candidates);

DELETE FROM exercise_muscle_groups
WHERE exercise_id IN (SELECT id FROM catalog_delete_candidates);

DELETE FROM exercises
WHERE id IN (SELECT id FROM catalog_delete_candidates);

DROP INDEX exercises_name_lower_trgm_idx;
UPDATE exercises
SET equipment = 'other'
WHERE id::text LIKE '10000000-%'
  AND equipment IN ('EZ bar', 'medicine ball', 'stability ball');
SET CONSTRAINTS ALL IMMEDIATE;
ALTER TABLE exercises DROP CONSTRAINT exercises_equipment_check;
ALTER TABLE exercises
  ADD CONSTRAINT exercises_equipment_check
  CHECK (equipment IS NULL OR equipment IN (
    'barbell', 'dumbbell', 'kettlebell', 'cable', 'machine',
    'plate-loaded machine', 'Smith machine', 'resistance band', 'bodyweight', 'other'
  ));
